// Nightly: keep every tenant's booking horizon provisioned (docs/BOOKING.md).
// Calls public.ensure_slots(sub_account_id, 21) for each crm_sub_accounts row,
// keeping a rolling 21 days of morning/midday/late_afternoon windows.
// ensure_slots is idempotent (ON CONFLICT DO NOTHING) — re-runs are free.
//
// BEFORE ACTIVATING, replace the two placeholders below:
//   SUPABASE_URL  = https://phtmarvmovozydxipmat.supabase.co  (the CRM project)
//   SERVICE_KEY   = Supabase Dashboard -> Settings -> API Keys -> service_role (secret)

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';

const sbHeaders = (extra = {}) => ({
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
  ...extra,
});

const tenants = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/crm_sub_accounts?select=sub_account_id`,
  headers: sbHeaders(),
  json: true,
});

const ensured = [];
for (const t of tenants ?? []) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/ensure_slots`,
    headers: sbHeaders(),
    body: { p_sub_account_id: t.sub_account_id, p_days_ahead: 21 },
    json: true,
  });
  ensured.push(t.sub_account_id);
}

return [{ json: { ensured: ensured.length, tenants: ensured } }];
